            // Beautiful, elegant Sparkline Chart
            VStack(alignment: .leading, spacing: ERDTheme.Spacing.compact) {
                Text("FPS TREND (30S)")
                    .font(ERDTheme.Typography.eyebrow)
                    .tracking(0.8)
